// ── test-d-f17-typecalc-rows.js ───────────────────────────────────────────
// Phase D finding F17: the type step is a ROW WALK, not a product.
//
// TypeCalc and Cmd_typecalc (src/battle_script_commands.c:1536-1590,
// :1355-1400) walk gTypeEffectiveness in row order (type-table.js, generated by
// gen-type-table.mjs and checked byte for byte against the ROM) and apply
// ModulateDmgByType (:1321-1326) per matching row: dmg = dmg * mul / 10, then 1
// if that gave 0 and mul is not 0. Two consequences the engine's
// floor(dmg * product) missed:
//   * each row floors on its own: Fire into Water/Grass is x0.5 THEN x2, so an
//     odd damage loses 1 (69 -> 34 -> 68, where the product kept 69);
//   * a x0 row followed by another matching row leaves 1: Ground into Skarmory
//     (Flying x0, then Steel x2). The battle still does nothing (the x0 row sets
//     MOVE_RESULT_DOESNT_AFFECT_FOE); the AI (retail) reads only the number --
//     its if_type_effectiveness sees 1, which is no category, so AI_CheckBadMove
//     does not take its x0 -10 (found by the handler/interpreter parity run:
//     Graveler's Brick Break into Gengar, where the defender-order walk gave 1).
// Found by: tools/ai-parity.mjs.
import { buildMon, calcDamage, typeCalcRows } from "./logic.js";

let failures = 0;
const ok = (c, m) => { if (!c) { failures++; console.log("  FAIL " + m); } else console.log("  ok   " + m); };
const J = JSON.stringify;
const mk = (species, over = {}) => buildMon({
  species, level: 50, nature: "Hardy", evs: {}, ability: "Pressure", item: null, moves: ["Tackle"], friendship: 255, ...over,
});

console.log("-- the row walk --");
{
  const r = (d, t, def, f = false) => typeCalcRows(d, t, def, f);
  ok(J(r(40, "Ground", ["Flying", "Steel"])) === J({ dmg: 1, noEffect: true }), `Ground into Flying/Steel: x0 then x2 leaves 1 (${J(r(40, "Ground", ["Flying", "Steel"]))})`);
  ok(J(r(40, "Fighting", ["Ghost", "Poison"])) === J({ dmg: 0, noEffect: true }), `Fighting into Ghost/Poison: Poison x0.5 first, the Ghost row last -> 0 (${J(r(40, "Fighting", ["Ghost", "Poison"]))})`);
  ok(J(r(40, "Ghost", ["Normal", "Psychic"])) === J({ dmg: 1, noEffect: true }), `Ghost into Normal/Psychic: x0 then x2 leaves 1`);
  ok(J(r(40, "Electric", ["Water", "Ground"])) === J({ dmg: 0, noEffect: true }), `Electric into Water/Ground: x2 then x0 -> 0`);
  ok(r(69, "Fire", ["Water", "Grass"]).dmg === 68, `Fire into Water/Grass floors per row: 69 -> 34 -> 68 (${r(69, "Fire", ["Water", "Grass"]).dmg})`);
  ok(r(69, "Water", ["Ground", "Grass"]).dmg === 68, `Water into Ground/Grass: the Grass x0.5 row precedes Ground x2 whatever the mon's type order: 68 (${r(69, "Water", ["Ground", "Grass"]).dmg})`);
  ok(J(r(40, "Normal", ["Ghost"], true)) === J({ dmg: 40, noEffect: false }), `Foresight stops the walk before Normal -> Ghost`);
  ok(J(r(40, "Normal", ["Ghost"])) === J({ dmg: 0, noEffect: true }), `and without it, x0`);
  ok(r(40, "Fire", ["Grass"]).dmg === 80 && r(40, "Fire", ["Grass", "Grass"]).dmg === 80,
    `a mono type's row applies once (types[1] only when it differs, :1575-1576): ${r(40, "Fire", ["Grass"]).dmg}, ${r(40, "Fire", ["Grass", "Grass"]).dmg}`);
  ok(r(1, "Fire", ["Water", "Dragon"]).dmg === 1, `x0.5 twice from 1 stays 1 (the min-1 rule)`);
}

console.log("-- calcDamage uses it --");
{
  // Ludicolo (Water/Grass) against a neutral clone of itself: rows give 2*floor(D/2).
  const lud = mk("Ludicolo", { ability: "Swift Swim" });
  const neutral = { ...lud, types: ["Normal"] };
  let odd = 0, all = 0, bad = [];
  for (const sp of ["Charizard", "Arcanine", "Houndoom", "Ninetales", "Rapidash", "Magmar", "Camerupt", "Torkoal", "Blaziken", "Typhlosion", "Flareon", "Moltres"]) {
    for (const mv of ["Flamethrower", "Fire Blast", "Ember", "Flame Wheel", "Overheat", "Heat Wave", "Fire Punch"]) {
      const a = mk(sp, { moves: [mv] });
      const D = calcDamage(a, neutral, mv, { rollFrac: 1 }), got = calcDamage(a, lud, mv, { rollFrac: 1 });
      all++;
      if (D % 2) odd++;
      if (got !== 2 * Math.floor(D / 2)) bad.push(`${sp} ${mv}: ${got} vs ${2 * Math.floor(D / 2)}`);
    }
  }
  ok(bad.length === 0 && odd > 0, `Fire into Ludicolo is 2*floor(D/2) on ${all} probes, ${odd} of them odd (where the product gave D): ${bad.join("; ")}`);
  // Earthquake into Skarmory: the battle does nothing; the AI's raw estimate is the walk's 1 x roll
  const sk = mk("Skarmory", { ability: "Keen Eye" });
  const gra = mk("Graveler", { ability: "Rock Head", moves: ["Earthquake"] });
  ok(calcDamage(gra, sk, "Earthquake", {}) === 0, `battle: Earthquake into Skarmory does 0`);
  ok(calcDamage(gra, sk, "Earthquake", { rollPercent: 100, aiEstimate: true }) === 1
    && calcDamage(gra, sk, "Earthquake", { rollPercent: 85, aiEstimate: true }) === 0,
    `AI estimate: 1 at roll 100, 1*85/100 = 0 at 85 (the consumers clamp)`);
}

console.log();
console.log(failures === 0 ? "ALL PASS -- F17 TypeCalc row walk green" : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);
